'use strict';
const D=window.ROOK_DATA;
const state={period:'all',product:'all',rank:'tickets',search:'',page:0,cluster:null};
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const base='https://miro.com/app/board/uXjVEUy5VSs=/?moveToWidget=';
const productFor=k=>k.startsWith('Supply')?'supply':k==='Billing'?'account':'dispatch';
const ticketProducts=new Map(D.tickets.map(t=>[t.ticket_number,productFor(Object.keys(D.groups).find(k=>D.groups[k].includes(t.ticket_number)))]));
const productName=p=>({dispatch:'Dispatch',supply:'Supply',account:'Account'}[p]);
const periodFor=t=>t.filed_at.slice(0,10)<'2026-08-12'?'before':t.filed_at.slice(0,10)==='2026-08-12'?'release':'after';
const periods={all:{days:71,label:'Full research window'},before:{days:44,label:'29 Jun–11 Aug 2026'},release:{days:1,label:'12 Aug 2026'},after:{days:26,label:'13 Aug–7 Sep 2026'}};
const filteredTickets=()=>D.tickets.filter(t=>(state.period==='all'||periodFor(t)===state.period)&&(state.product==='all'||ticketProducts.get(t.ticket_number)===state.product));
const titleFor=k=>D.titles[k].replace(/^(Dispatch|Supply|Account|Positive) \| /,'');
const frameFor=k=>D.frames.find(f=>f.title===D.titles[k]);
function clusterStats(tickets){return Object.entries(D.groups).filter(([k])=>state.product==='all'||productFor(k)===state.product).map(([key,ids])=>{const ts=tickets.filter(t=>ids.includes(t.ticket_number));return {key,tickets:ts.length,filers:new Set(ts.map(t=>t.filed_by)).size,interviewees:new Set(D.interviewNotes.filter(i=>i[3]===key).map(i=>i[0])).size};}).filter(x=>x.tickets>0).sort((a,b)=>b[state.rank]-a[state.rank]||b.tickets-a.tickets||b.filers-a.filers||b.interviewees-a.interviewees);}
function renderMetrics(){const ts=filteredTickets();$('ticket-total').textContent=ts.length;$('filer-total').textContent=new Set(ts.map(t=>t.filed_by)).size;$('daily-total').textContent=(ts.length/periods[state.period].days).toFixed(2);$('ticket-caption').textContent=periods[state.period].label;$('daily-caption').textContent=periods[state.period].days+' calendar days in scope';}
function renderTrend(){const start=new Date('2026-06-29T00:00:00Z'),days=Array.from({length:71},(_,i)=>new Date(start.getTime()+i*86400000).toISOString().slice(0,10));const ts=D.tickets.filter(t=>state.product==='all'||ticketProducts.get(t.ticket_number)===state.product);const values=days.map(day=>ts.filter(t=>t.filed_at.slice(0,10)===day).length);const max=Math.max(6,...values),w=580,h=210,l=29,r=12,top=14,b=32,cw=w-l-r, ch=h-top-b,step=cw/71;const sx=i=>l+i*step;const sy=n=>top+ch-n/max*ch;let svg=`<svg viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">`;for(let j=0;j<=3;j++){const n=Math.round(max*j/3),y=sy(n);svg+=`<line x1="${l}" x2="${w-r}" y1="${y}" y2="${y}" stroke="#e9ede6"/><text x="${l-10}" y="${y+3}" text-anchor="end" font-size="8" fill="#95a193">${n}</text>`;}values.forEach((v,i)=>{const active=state.period==='all'||(days[i]<'2026-08-12'?'before':days[i]==='2026-08-12'?'release':'after')===state.period;svg+=`<rect x="${sx(i)+1}" y="${sy(v)}" width="${Math.max(1,step-2)}" height="${v/max*ch}" rx="1" fill="${i<44?'#b3c7b4':'#789f83'}" opacity="${active?1:.22}"><title>${days[i]}: ${v} tickets</title></rect>`;});const release=sx(44)+step/2;svg+=`<line x1="${release}" x2="${release}" y1="4" y2="${h-b+4}" stroke="#b37b4c" stroke-dasharray="3 3"/><rect x="${release-31}" y="0" width="62" height="17" rx="3" fill="#f5ecde"/><text x="${release}" y="11" text-anchor="middle" font-size="7" fill="#9b774d">12 AUG · 4.2</text>`;[[0,'29 Jun'],[14,'13 Jul'],[28,'27 Jul'],[44,'12 Aug'],[56,'24 Aug'],[70,'07 Sep']].forEach(([i,label])=>svg+=`<text x="${sx(i)}" y="${h-9}" text-anchor="${i===0?'start':i===70?'end':'middle'}" font-size="8" fill="#95a193">${label}</text>`);svg+='</svg>';$('trend').innerHTML=svg;$('trend').setAttribute('aria-label',`Daily support filings, ${ts.length} tickets in full window for ${state.product==='all'?'all products':productName(state.product)}. Chart shows all dates; selected period is highlighted.`);}
function renderClusters(){const list=clusterStats(filteredTickets()).slice(0,5),max=list[0]?.[state.rank]||1;$('cluster-chart').innerHTML=list.length?list.map(c=>`<div class="cluster-row"><div class="cluster-label"><button data-cluster="${esc(c.key)}" title="Filter the evidence library to this cluster">${esc(titleFor(c.key))}</button><strong>${c[state.rank]} ${state.rank==='tickets'?'tickets':'filers'}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${c[state.rank]/max*100}%"></div></div></div>`).join(''):'<p class="chart-note">No tickets in this product and period.</p>';document.querySelectorAll('[data-cluster]').forEach(b=>b.onclick=()=>{state.cluster=b.dataset.cluster;state.page=0;renderTable();$('evidence').scrollIntoView({behavior:'smooth'});});}
function evidenceTickets(){const term=state.search.toLowerCase();return filteredTickets().filter(t=>(!state.cluster||D.groups[state.cluster].includes(t.ticket_number))&&(!term||[t.subject,t.body,t.filed_by,t.about_responder,t.ticket_number].join(' ').toLowerCase().includes(term))).sort((a,b)=>b.ticket_number-a.ticket_number);}
function renderTable(){const all=evidenceTickets(),pages=Math.max(1,Math.ceil(all.length/8));state.page=Math.min(state.page,pages-1);const part=all.slice(state.page*8,state.page*8+8);$('ticket-rows').innerHTML=part.length?part.map(t=>`<tr tabindex="0" role="button" aria-label="Read ticket ${t.ticket_number}: ${esc(t.subject)}" data-ticket="${t.ticket_number}"><td>#${t.ticket_number}<small>${t.filed_at.slice(0,10)}</small></td><td>${esc(t.subject)}<small>${esc(t.about_responder)}</small></td><td>${esc(t.filed_by)}</td><td>${productName(ticketProducts.get(t.ticket_number))}</td><td><span class="status ${t.status}">${t.status==='open'?'Open':'Closed'}</span></td><td>↗</td></tr>`).join(''):'<tr><td colspan="6">No matching tickets. Try another search or scope.</td></tr>';$('result-count').textContent=all.length?`${state.page*8+1}–${Math.min((state.page+1)*8,all.length)} of ${all.length} tickets`:'0 tickets';$('page-label').textContent=`${state.page+1} / ${pages}`;$('prev').disabled=state.page===0;$('next').disabled=state.page>=pages-1;$('evidence-caption').textContent=state.cluster?`Cluster: ${titleFor(state.cluster)} · click here to clear cluster filter`:'Selected scope · click a row to read the original report';$('evidence-caption').style.cursor=state.cluster?'pointer':'default';$('evidence-caption').onclick=()=>{state.cluster=null;state.page=0;renderTable();};document.querySelectorAll('[data-ticket]').forEach(row=>{row.onclick=()=>openTicket(Number(row.dataset.ticket));row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();row.click();}};});}
function openTicket(id){const t=D.tickets.find(t=>t.ticket_number===id);$('modal-ticket-id').textContent=`TICKET #${id} / ${t.status.toUpperCase()}`;$('modal-title').textContent=t.subject;$('modal-meta').textContent=`${t.filed_at.slice(0,10)} · ${t.filed_by} · ${t.about_responder}`;$('modal-body').textContent=t.body;$('modal-clusters').innerHTML=Object.entries(D.groups).filter(([,ids])=>ids.includes(id)).map(([k])=>`<a class="cluster-link" target="_blank" rel="noopener" href="${base+frameFor(k).id}">${esc(titleFor(k))} ↗</a>`).join('');$('ticket-dialog').showModal();}
function render(){renderMetrics();renderTrend();renderClusters();renderTable();}
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{state.period=b.dataset.period;state.page=0;state.cluster=null;document.querySelectorAll('[data-period]').forEach(x=>{const yes=x===b;x.classList.toggle('selected',yes);x.setAttribute('aria-pressed',String(yes));});render();});
$('product').onchange=e=>{state.product=e.target.value;state.page=0;state.cluster=null;render();};$('rank-by').onchange=e=>{state.rank=e.target.value;renderClusters();};$('search').oninput=e=>{state.search=e.target.value;state.page=0;renderTable();};$('prev').onclick=()=>{state.page--;renderTable();};$('next').onclick=()=>{state.page++;renderTable();};
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const rect=d.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)d.close();}}));
let decisionKey;const decisionTitles={workload:'Investigate quiet and uneven workloads',timing:'Validate time available to answer',filters:'Stabilize saved filter behavior'};
document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>{decisionKey=b.dataset.decision;$('decision-title').textContent=decisionTitles[decisionKey];let draft={};try{draft=JSON.parse(localStorage.getItem('rook-decision-'+decisionKey)||'{}');}catch{}$('decision-disposition').value=draft.disposition||'Investigate next';$('decision-notes').value=draft.notes||'';$('saved-message').textContent=draft.notes?'Draft restored.':'';$('decision-dialog').showModal();});
$('decision-form').onsubmit=e=>{e.preventDefault();try{localStorage.setItem('rook-decision-'+decisionKey,JSON.stringify({disposition:$('decision-disposition').value,notes:$('decision-notes').value}));$('saved-message').textContent='Saved in this browser.';}catch{$('saved-message').textContent='Browser storage unavailable; copy your notes before closing.';}};
$('export').onclick=()=>{const csvValue=s=>'"'+String(s).replace(/"/g,'""')+'"';const rows=[['ticket_number','filed_at','handler','responder','subject','body','status','product','clusters'],...evidenceTickets().map(t=>[t.ticket_number,t.filed_at.slice(0,10),t.filed_by,t.about_responder,t.subject,t.body,t.status,productName(ticketProducts.get(t.ticket_number)),Object.entries(D.groups).filter(([,ids])=>ids.includes(t.ticket_number)).map(([k])=>titleFor(k)).join('; ')])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(csvValue).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`rook-tickets-${state.period}-${state.product}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{document.querySelectorAll('nav a').forEach(x=>x.classList.toggle('active',x===a));});
render();
